def statement(invoice, plays):
    total_amount, volume_credits = calculate_totals(invoice['performances'], plays)
    result = format_statement(invoice['customer'], total_amount, volume_credits, invoice['performances'], plays)
    return result
def format_currency(amount):
    return f"${amount:,.2f}"
def calculate_totals(performances, plays):
    total_amount = 0
    volume_credits = 0
    for perf in performances:
        play = plays[perf['playID']]
        this_amount = calculate_amount(play, perf['audience'])
        volume_credits += calculate_credits(play, perf['audience'])
        total_amount += this_amount
    return total_amount, volume_credits
def calculate_amount(play, audience):
    if play['type'] == 'tragedy':
        this_amount = 40000
        if audience > 30:
            this_amount += 1000 * (audience - 30)
    elif play['type'] == 'comedy':
        this_amount = 30000
        if audience > 20:
            this_amount += 10000 + 500 * (audience - 20)
        this_amount += 300 * audience
    else:
        raise ValueError(f"Unknown type: {play['type']}")
    return this_amount
def calculate_credits(play, audience):
    credits = max(audience - 30, 0)
    if play['type'] == 'comedy':
        credits += audience // 5
    return credits
def format_statement(customer, total_amount, volume_credits, performances, plays):
    result = f"Statement for {customer}\n"
    for perf in performances:
        play = plays[perf['playID']]
        result += f" {play['name']}: {format_currency(calculate_amount(play, perf['audience']) / 100)} ({perf['audience']} seats)\n"
    result += f"Amount owed is {format_currency(total_amount / 100)}\n"
    result += f"You earned {volume_credits} credits\n"
    return result
